WITH scoped AS (SELECT q.mktcode,q.tgtcode,q.bizdate,(q.lastPx/10000.0)*q.totalShare AS metric FROM `newzl`.`hsj_stock_hq_basic` q WHERE q.bizdate='2026-04-14' AND (q.mktcode=1 AND q.tgtcode BETWEEN '688000' AND '688999')), industry_stat AS (SELECT i.industry_code,MIN(s.metric) AS baseline FROM scoped s INNER JOIN `findsl_ext`.`industry_membership` i ON i.mktcode=s.mktcode AND i.tgtcode=s.tgtcode WHERE i.snapshot_id='baostock-industry-2026-07-13-4d38e6963e35' AND i.classification_system='证监会行业分类' AND i.industry_level='industry' GROUP BY i.industry_code) SELECT s.mktcode,s.tgtcode,s.bizdate FROM scoped s INNER JOIN `findsl_ext`.`industry_membership` i ON i.mktcode=s.mktcode AND i.tgtcode=s.tgtcode INNER JOIN industry_stat a ON a.industry_code=i.industry_code WHERE i.snapshot_id='baostock-industry-2026-07-13-4d38e6963e35' AND i.classification_system='证监会行业分类' AND i.industry_level='industry' AND s.metric>a.baseline;
